e IS NULL;
UPDATE companies SET description='PCB Prime, Inc. operates from Aurora, Colorado, drawing on decades of experience in the printed circuit board fabrication and assembly industry. The company does not disclose a specific founding year or ownership structure, but describes itself as the culmination of extensive industry experience aimed at delivering consistent quality and dependable lead times.

The company provides rigid PCB fabrication up to 42 layers using materials such as FR4, aluminum, Rogers, and Nelco, with capabilities including controlled impedance, blind and buried vias (HDI), via-in-pad, and Class II/III compliance. It also offers PCB assembly services — surface mount, through-hole, BGA, fine-pitch placement, X-ray inspection, and functional testing — along with flex, rigid-flex, stencils, cables, full box builds, and engineering support. All manufacturing is performed through a qualified network of partner facilities that are ISO 9001:2015 and UL certified, RoHS, REACH, and conflict-mineral compliant. Order volumes range from a single piece to one million pieces, with production lead times as short as two business days.

Its prototype program offers fixed pricing for 2- to 8-layer boards with lead times of six to eleven days.

The company emphasizes several differentiators: no tooling or test charges on bare boards, a single point of contact from quote to shipment, a diversified partner network to mitigate production risk, sales engineers with a minimum of 15 years'' industry experience, and a commitment to availability and flexibility in scheduling and invoicing.', certifications=ARRAY['ISO 9001:2015','UL certified','RoHS compliant','REACH compliant','Conflict Mineral compliant']::text[], profile='{"capabilities": ["Rigid PCB fabrication (up to 42 layers)", "Controlled impedance", "Blind and buried vias (HDI)", "Via in pad / active pad", "Class II and Class III compliance", "PCB assembly (SMT, through-hole, BGA, fine pitch)", "X-ray inspection", "Functional testing", "Flex PCB fabrication", "Rigid-flex PCB fabrication", "Stencil manufacturing", "Cable assembly", "Full box build", "Engineering services", "Turnkey, kitted, and consigned assembly", "Lead-free and leaded assembly", "Prototype and production volumes (1 to 1,000,000 pieces)"], "industries": ["Contract electronics assembly", "Electronics manufacturing", "Prototype development", "Hobbyist and education markets"], "materials": ["FR4", "Aluminum", "Rogers", "Nelco", "Exotic laminates"], "equipment": [], "volume": "1 to 1,000,000 pieces", "lead_time": "As fast as 2 business days for production; prototype services 6-11 days depending on layer count", "tolerances": "", "built_on": ["No tooling or test charges on bare boards", "Single point of contact from quote to shipment", "Diversified manufacturing partner network for risk mitigation", "Sales engineers with minimum 15 years industry experience", "Quick-turn prototypes shipped in as little as 2 business days"], "facts_used": ["Headquarters: Aurora, Colorado -> db", "Business description: printed circuit board manufacturer with over 20 years experience -> db", "Rigid PCB capabilities: up to 42 layers, FR4, Aluminum, Rogers, Nelco, controlled impedance, blind/buried vias, via in pad,